class ExpressionEvaluator:
    def __init__(self, expr: str):
        self.expr = expr
        self.pos = 0

    def parse(self):
        return self.expr_addition()

    def expr_addition(self):
        result = self.expr_multiplication()
        while self.pos < len(self.expr):
            if self.current_char() == '+':
                self.pos += 1
                result += self.expr_multiplication()
            elif self.current_char() == '-':
                self.pos += 1
                result -= self.expr_multiplication()
            else:
                break
        return result

    def expr_multiplication(self):
        result = self.expr_primary()
        while self.pos < len(self.expr):
            if self.current_char() == '*':
                self.pos += 1
                result *= self.expr_primary()
            elif self.current_char() == '/':
                self.pos += 1
                divisor = self.expr_primary()
                if divisor == 0:
                    raise ZeroDivisionError("division by zero")
                result /= divisor
            else:
                break
        return result

    def expr_primary(self):
        if self.current_char() == '(':
            self.pos += 1
            result = self.expr_addition()
            self.pos += 1  # Skip the closing parenthesis
            return result
        else:
            num = self.parse_number()
            return num

    def parse_number(self):
        start_pos = self.pos
        while self.pos < len(self.expr) and (self.current_char().isdigit() or self.current_char() == '.'):
            self.pos += 1
        return float(self.expr[start_pos:self.pos])

    def current_char(self):
        if self.pos < len(self.expr):
            return self.expr[self.pos]
        return None


